with open(dashboard_path, "r", encoding="utf-8") as f:
    html = f.read()

# Replace testMatrixData in html
json_str = json.dumps(all_modules, indent=6, ensure_ascii=False)
js_replacement = f"const testMatrixData = {json_str};"

pattern = r"const testMatrixData = \[[\s\S]*?\];\s*// LocalStorage Keys"
replacement = f"{js_replacement}\n\n    // LocalStorage Keys"

new_html, count = re.subn(pattern, replacement, html)
print("Replaced count:", count)

if count > 0:
    with open(dashboard_path, "w", encoding="utf-8") as f:
        f.write(new_html)
    print("Successfully updated interactive_test_dashboard.html with ultra-explicit navigation click steps!")
else:
    print("Failed to find pattern to replace.")
